\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Lancet-Inspired Color Theme ──
\definecolor{primary}{HTML}{0A2540}      % deep navy
\definecolor{secondary}{HTML}{0891B2}    % clinical teal
\definecolor{accent}{HTML}{C8963E}       % muted gold
\definecolor{bgposter}{HTML}{F5F7FA}     % subtle cool grey tint
\definecolor{navybg}{HTML}{EEF2F7}       % navy card background
\definecolor{tealbg}{HTML}{ECFDF9}       % teal card background
\definecolor{goldbg}{HTML}{FFFCF0}       % gold card background
\definecolor{navytitlebg}{HTML}{DEE5ED}  % navy card title bar
\definecolor{tealtitlebg}{HTML}{CFFAF5}  % teal card title bar
\definecolor{goldtitlebg}{HTML}{FEF7E0}  % gold card title bar
\definecolor{textdark}{HTML}{1A1A2E}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFF1F0} % warm highlight for anchor stat
\definecolor{warnbg}{HTML}{FFFBEB}        % warning tint for bias stat

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=goldtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!12!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR (rows 1-4, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{90}\selectfont\bfseries Artificial Intelligence in Clinical Decision-Making}\\[10pt]
  {\fontsize{44}{52}\selectfont\color{white!85} Performance, Safety, and Implementation Gaps}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!60} The Lancet Digital Health \textbullet\ AI in Clinical Medicine Symposium}
}

% ═══════════════════════════════════════════
% STAT BANNER (rows 4-6, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{primary!25},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  % Anchor stat: <5% — visually dominant
  \begin{minipage}[c]{0.38\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{82}{98}\selectfont\bfseries\color{secondary}\textbf{<}5\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark}\textbf{Prospective Validation Rate}}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray}of published AI models}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Sensitivity comparison
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!30}{navybg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary}87.5\%}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{AI Sensitivity}}\\[8pt]
      {\color{primary!30}\rule{0.7\linewidth}{2pt}}\\[8pt]
      {\fontsize{60}{72}\selectfont\bfseries\color{textgray}78.2\%}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{Clinician Sensitivity}}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Bias assessment — warning
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!60}{warnbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent!70!black}18\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{Studies Reporting}}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{Bias Assessment}}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════
% ROW A (rows 6-11): Background, Diagnostic Performance, Domain Table
% ═══════════════════════════════════════════

% Col 1: Background & Motivation
\posterbox[tealcard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item AI-based clinical decision support systems (CDSS) show growing evidence across diagnostic, prognostic, and therapeutic domains
    \item Performance gains are largest in \textbf{medical imaging} — radiology, dermatology, ophthalmology
    \item Despite promising controlled-setting results, \textbf{translation to routine clinical practice remains critically limited}
  \end{itemize}
  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{30}{40}\selectfont\color{textdark}
    $\Rightarrow$ \textbf{The research-to-practice gap} is the central challenge in clinical AI today.
  }}
}

% Col 2: Diagnostic Performance
\posterbox[goldcard, title={Diagnostic Performance}
]{name=diagperf, column=2, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  % Visual bar comparison
  \vspace{4pt}
  \centering
  {\fontsize{28}{34}\selectfont\bfseries\color{textdark}Diagnostic Sensitivity}\\[6pt]
  % AI bar
  \begin{minipage}{0.92\linewidth}
    \raggedright
    {\fontsize{30}{38}\selectfont\bfseries\color{primary}AI}\\[2pt]
    \colorbox{primary}{\color{white}\rule{0.875\linewidth}{0pt}\rule{0.875\linewidth}{22pt}}\\[2pt]
    {\fontsize{36}{44}\selectfont\bfseries\color{primary}87.5\%}
  \end{minipage}\\[10pt]
  % Clinician bar
  \begin{minipage}{0.92\linewidth}
    \raggedright
    {\fontsize{30}{38}\selectfont\bfseries\color{textgray}Clinician}\\[2pt]
    \colorbox{primary!30}{\color{white}\rule{0.782\linewidth}{0pt}\rule{0.782\linewidth}{22pt}}\\[2pt]
    {\fontsize{36}{44}\selectfont\bfseries\color{textgray}78.2\%}
  \end{minipage}\\[12pt]
  % Specificity and turnaround
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    \textbf{Specificity:} AI 93.1\% \hspace{4pt}vs.\hspace{4pt} Clinician 91.4\%
  }}\\[8pt]
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    \textbf{Turnaround time:} reduced by \textbf{32\%} with AI assistance
  }}
}

% Col 3: Performance by Domain
\posterbox[goldcard, title={Performance by Clinical Domain}
]{name=domaintable, column=3, between=row6 and row11}{
  \centering
  \vspace{4pt}
  \renewcommand{\arraystretch}{1.5}
  \fontsize{26}{34}\selectfont
  \begin{tabular}{lcccc}
    \rowcolor{accent!15}
    \textbf{Domain} & \textbf{AI Sens} & \textbf{Clin Sens} & \textbf{AI Spec} & \textbf{Clin Spec} \\
    Radiology & 89.3\% & 79.8\% & 94.0\% & 92.1\% \\
    \rowcolor{accent!8}
    Dermatology & 86.7\% & 76.5\% & 91.8\% & 89.4\% \\
    Ophthalmology & 90.1\% & 82.3\% & 95.2\% & 93.7\% \\
    \rowcolor{accent!8}
    Pathology & 84.0\% & 74.1\% & 91.5\% & 90.0\% \\
  \end{tabular}\\[8pt]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{Median sensitivity and specificity across 400+ studies.}}
}

% ═══════════════════════════════════════════
% ROW B (rows 11-16): Safety/Bias, Implementation Gap, Barriers
% ═══════════════════════════════════════════

% Col 1: Safety, Bias & Health Equity
\posterbox[navycard, title={Safety, Bias \& Health Equity}
]{name=safety, column=1, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item Only \textbf{18\%} of published studies report formal demographic bias assessment
    \item Among those, \textbf{5--12 pp} sensitivity disparities for underrepresented populations — especially dermatology AI on darker skin tones
    \item Adverse safety events: \textbf{$<$1\%} in prospective trials, but \textbf{under-reporting is suspected}
    \item No standardised AI safety-reporting framework exists — a critical regulatory gap
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\color{textdark}
    \textbf{Warning:} Bias assessment remains the exception, not the norm.
  }}
}

% Col 2: Translational Implementation Gap
\posterbox[tealcard, title={The Translational Implementation Gap}
]{name=impgap, column=2, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \vspace{4pt}
  \centering
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{30}{38}\selectfont\color{textdark}\textbf{FDA-Cleared AI/ML Devices}}\\[4pt]
    {\fontsize{64}{76}\selectfont\bfseries\color{secondary}\textbf{692}}\vspace{6pt}
  }}\\[8pt]
  \vspace{2pt}
  \colorbox{stathighlight}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{30}{38}\selectfont\color{textdark}Yet only}\\[4pt]
    {\fontsize{72}{86}\selectfont\bfseries\color{secondary}\textbf{$<$5\%}}\\[4pt]
    {\fontsize{30}{38}\selectfont\color{textdark}prospectively validated}\vspace{6pt}
  }}\\[10pt]
  \begin{itemize}[itemsep=10pt]
    \item Regulatory clearance $\neq$ real-world evidence
    \item Vast gap between published models and bedside deployment
  \end{itemize}
}

% Col 3: Key Barriers
\posterbox[navycard, title={Key Barriers to Deployment}
]{name=barriers, column=3, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{Data infrastructure:} Fragmented EHR systems, lack of interoperability standards
    \item \textbf{Regulatory uncertainty:} Frameworks evolving slower than AI development
    \item \textbf{Clinician trust:} Insufficient explainability and transparency of model outputs
    \item \textbf{Economic evidence:} Limited cost-effectiveness analyses to justify investment
    \item \textbf{Workflow integration:} Poor alignment of AI tools with clinical workflows
  \end{itemize}
}

% ═══════════════════════════════════════════
% ROW C (rows 16-20): Recommendations, Key Takeaways
% ═══════════════════════════════════════════

% Col 1: Recommendations (1-3)
\posterbox[goldcard, title={Recommendations}
]{name=recs1, column=1, between=row16 and bottom}{
  \fontsize{30}{40}\selectfont
  \begin{enumerate}[itemsep=16pt]
    \item \textbf{Mandate prospective validation} before clinical deployment, including multi-site, diverse-population trials
    \item \textbf{Standardise bias auditing} using demographic-stratified performance reporting as a publication requirement
    \item \textbf{Develop shared safety-reporting registries} analogous to pharmacovigilance systems for AI-CDSS
  \end{enumerate}
}

% Col 2: Recommendations (4-5) + Infrastructure
\posterbox[goldcard, title={}
]{name=recs2, column=2, between=row16 and bottom}{
  \fontsize{30}{40}\selectfont
  \begin{enumerate}[itemsep=16pt]
    \setcounter{enumi}{3}
    \item \textbf{Invest in interoperability} through open data standards (FHIR, OMOP)
    \item \textbf{Prioritise explainability research} to build clinician and patient trust in AI-augmented care
  \end{enumerate}
  \vspace{10pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\color{textdark}
    $\Rightarrow$ \textbf{Closing the gap} requires coordinated action across the research, regulatory, and healthcare delivery ecosystem.
  }}
}

% Col 3: Key Takeaways
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row16 and bottom}{
  \fontsize{32}{42}\selectfont\color{textdark}
  \begin{itemize}[itemsep=16pt]
    \item \textbf{AI improves diagnostic accuracy} — meaningful gains in sensitivity (+9.3 pp) and specificity over clinician-only workflows
    \item \textbf{Real-world evidence is alarmingly scarce} — fewer than 5\% of published models reach prospective clinical validation
    \item \textbf{Safety and equity remain under-evaluated} — standardised bias auditing and safety reporting are urgent priorities
  \end{itemize}
}

\end{tcbposter}
\end{document}
